import io
import random
import numpy as np
import pandas as pd


def load_examples(csv_text, features, label):
    df = pd.read_csv(io.StringIO(csv_text))
    df = df.dropna(subset=features + [label])
    return df[features].astype(float).values.tolist(), df[label].tolist()


def fit_centroids(X, y):
    X = np.array(X, dtype=float)
    centroids = {}
    for label in set(y):
        rows = [i for i in range(len(y)) if y[i] == label]
        centroids[label] = X[rows].mean(axis=0).tolist()
    return centroids


def predict_centroids(centroids, X):
    labels = sorted(centroids)
    out = []
    for x in np.array(X, dtype=float):
        dists = [float(np.sum((x - np.array(centroids[l])) ** 2)) for l in labels]
        out.append(labels[dists.index(min(dists))])
    return out


def majority_label(labels):
    counts = {}
    for label in labels:
        counts[label] = counts.get(label, 0) + 1
    return max(sorted(counts), key=counts.get)


def accuracy(predicted, actual):
    return sum(p == a for p, a in zip(predicted, actual)) / len(actual)


def run_pipeline(csv_text, features, label, test_fraction, seed):
    X, y = load_examples(csv_text, features, label)
    positions = list(range(len(y)))
    random.Random(seed).shuffle(positions)
    cut = int(len(y) * test_fraction)
    test, train = positions[:cut], positions[cut:]
    if not test or not train:
        raise ValueError('both the training set and the test set need at least one example')
    X_train, y_train = [X[i] for i in train], [y[i] for i in train]
    X_test, y_test = [X[i] for i in test], [y[i] for i in test]
    guess = majority_label(y_train)
    model = fit_centroids(X_train, y_train)
    return {'n_train': len(train), 'n_test': len(test), 'baseline_label': guess,
            'baseline': accuracy([guess] * len(y_test), y_test),
            'model': accuracy(predict_centroids(model, X_test), y_test)}

